#!/usr/bin/env python3
"""Present the exact N13 exclusion and the live cross-catalogue audit."""
from pathlib import Path
import html,json,re,hashlib
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]
def m(x,display=True):
 tag='div'if display else'span'
 return f'<{tag} class="math" data-display="{str(display).lower()}" data-tex="{html.escape(x,quote=True)}"></{tag}>'
def p(x):return '<p>'+x+'</p>'
def a(url,text):return f'<a href="{html.escape(url,quote=True)}">{text} ↗</a>'
def links(items):return '<div class="proof-links">'+''.join(a(u,t)for u,t in items)+'</div>'
def main():
 report=json.loads((HERE/'independent-verification.json').read_text());assert report['passed']
 assert report['traceCertificate']['traceAnnihilatesWholeKernelExactly']
 assert report['certificateSHA256']==hashlib.sha256((HERE/'certificate.json').read_bytes()).hexdigest()
 cross=json.loads((HERE/'cross-catalogue-audit.json').read_text())
 css=re.search(r'<style>(.*?)</style>',(ROOT/'research/t2-qec-upper/index.html').read_text(),re.S).group(1)
 css+='\n.math{max-width:100%;overflow-x:auto}.badge{font-size:.8rem;letter-spacing:.08em;text-transform:uppercase;color:#1c6253}.scroll{overflow-x:auto}summary{cursor:pointer;font-weight:600}details{margin:1.4rem 0}.proof-step{border-left:3px solid #b8c9bd;padding-left:1.2rem;margin:2rem 0}.file-note{font-size:.9rem;color:#64716b}section{scroll-margin-top:1rem}'
 b='<p class="eyebrow">Anticoherent subspaces · Exact nonexistence certificate</p>'+a('../../index.html#n=13&t=4','← Selected catalogue entry')
 b+='<h1>Thirteen qubits: maximum pure AC order is three</h1>'
 b+='<div class="result"><span class="badge">Proved · arbitrary complex states</span>'+m(r'\boxed{K(13,t)=0\quad(t\ge4),\qquad t_{\max}(13)=3.}')+p('An exact four-copy trace identity rules out every fourth-order anticoherent state on thirteen symmetric qubits. The existing exact third-order states attain the largest possible order. This closes both formerly unresolved cells at orders four and five.')+'</div>'
 b+=p('The proof uses necessary equations for a rotation-averaged moment of a hypothetical state. Their complete solution space has trace zero; normalization requires trace one. Every decisive calculation uses integers or rational numbers.')
 b+='<nav class="jump-links" aria-label="On this page"><a href="#proof">Proof</a><a href="#certificate">Exact certificate</a><a href="#comparison">Catalogue cross-check</a><a href="#controls">Positive controls</a></nav>'
 b+='<section id="proof"><h2>A contradiction from four copies</h2>'
 b+='<div class="proof-step"><h3>1. Construct a normalized invariant moment</h3>'+p('Suppose '+m(r'|\psi\rangle\in V_{13/2}',False)+' is fourth-order AC and put '+m(r'\rho=|\psi\rangle\langle\psi|',False)+'. Its rotational average on four identical copies is')+m(r'X=\int_{\mathrm{SU}(2)}(U\rho U^\dagger)^{\otimes4}\,dU,\qquad\operatorname{Tr}X=1.')+p('It acts on '+m(r'\operatorname{Sym}^4(V_{13/2})',False)+', of dimension '+m(r'\binom{17}{4}=2380',False)+'. Rotation preserves anticoherence, so its rank-one through rank-four contraction equations are')+m(r'\operatorname{Tr}_1\!\left[(T_{\ell0}\otimes I^{\otimes3})X\right]=0,\qquad\ell=1,2,3,4.')+'</div>'
 b+='<div class="proof-step"><h3>2. Reduce to exact invariant coordinates</h3>'+p('Angular-momentum decomposition describes the real part of the invariant moment using 331 real symmetric multiplicity coordinates '+m(r'\mathbf b',False)+'. Taking these real parts preserves the equations and physical trace, so arbitrary complex state amplitudes are covered.')+m(r'A\mathbf b=0,\qquad A\in\mathbb Z^{320\times331},\qquad\operatorname{rank}A=320.')+p('The selected equations are reconstructed directly from symmetrized tensor words. Rank is certified modulo the prime 1000003. An explicit integer matrix '+m(r'R',False)+' gives the entire kernel:')+m(r'AR=0,\qquad R\in\mathbb Z^{331\times11},\qquad\operatorname{rank}R=11,\qquad\mathbf b=R\mathbf y.')+'</div>'
 b+='<div class="proof-step"><h3>3. The physical trace vanishes on that kernel</h3>'+p('Reconstruct the physical trace functional '+m(r'\tau',False)+' from the actual Hilbert-space inner product. Exact arithmetic gives')+m(r'\boxed{\tau R=0.}')+p('Every solution of the necessary AC equations therefore satisfies')+m(r'\operatorname{Tr}X=\tau\mathbf b=\tau R\mathbf y=0,')+p('contradicting '+m(r'\operatorname{Tr}X=1',False)+'. This excludes fourth-order AC. Every higher order is excluded because it includes the same lower-rank conditions.')+'</div>'
 b+=links([('proof.tex','Full LaTeX proof, normalization and equations'),('../../index.html#n=13&t=3&subspace=radical-n13-k2-t3','Existing exact third-order subspace')])+'</section>'
 b+='<section id="certificate"><h2>A portable exact certificate</h2>'+p('The certificate contains integer highest-weight bases, 320 selected contraction rows, an eleven-dimensional integer kernel, and the rational physical trace. The independent verifier imports no discovery code and uses only the Python standard library.')
 b+='<div class="scroll"><table><thead><tr><th>Check</th><th>Exact result</th></tr></thead><tbody>'
 for label,value in [('Four-copy Hilbert-space dimension','2380'),('Real invariant coordinates','331'),('Independent contraction equations','320'),('Kernel dimension','11'),('Prime used for rank certification','1000003'),('Trace on the complete kernel','Identically zero')]:b+=f'<tr><td>{label}</td><td>{value}</td></tr>'
 b+='</tbody></table></div>'+p('The verifier also reconstructs the trace by summing every descendant word and independently confirms the shorter highest-weight formula. A numerical rank estimate or failed state search is not used to establish nonexistence.')
 b+='<pre><code>python3 verify_independently.py</code></pre>'+p('Place the verifier beside the certificate. The resulting report records the certificate’s SHA-256 digest.')
 b+=links([('certificate.json','Exact certificate · 3.5 MB'),('verify_independently.py','Standalone exact verifier'),('independent-verification.json','Independent successful verification')])+'</section>'
 b+='<section id="comparison"><h2>Cross-check against the pure AC-state catalogue</h2>'+p('The two catalogues now agree on all '+str(cross['sharedEntriesChecked'])+' shared entries. Exact existence witnesses remain distinct from numerical library files. The comparison corrected seven previously unknown pure-state cells and added two missing exact representatives:')
 b+='<div class="scroll"><table><thead><tr><th>Parameters</th><th>Correction in the pure-state catalogue</th></tr></thead><tbody>'
 for nt,result in [('N=13, t=4 and 5','Proved impossible by this four-copy certificate'),('N=15, t=6','Proved impossible by the rectangular-tensor bound'),('N=16, t=6','Proved impossible by the exact equality obstruction'),('N=16 and 18, t=7','Proved impossible by the rectangular-tensor bound'),('N=20, t=7','Proved impossible by the odd-order equality obstruction'),('N=14 and 17, t=4','Added certified radical representatives and Majorana views')]:b+=f'<tr><td>{nt}</td><td>{result}</td></tr>'
 b+='</tbody></table></div>'
 b+=p('The local Liège library contains '+str(cross['localDickeFileCount'])+' Dicke-basis files; their reported orders all pass numerical reduced-state checks. At thirteen qubits, '+m(r'\texttt{acsdk.13.3.txt}',False)+' reports order three and has a fourth-reduction deviation of approximately '+m(r'0.0647096',False)+'. There is no fourth-order Dicke file. That file inventory is consistent with the theorem but is not part of its proof.')
 b+=p('In filenames of the form '+m(r'\texttt{acs.N.t.g.txt}',False)+', the last index describes Majorana-point multiplicity; it is not an additional AC order.')
 b+=links([('../../../anticoherent-state-catalogue/index.html#n=13&t=4','Pure AC-state catalogue'),('cross-catalogue-audit.json','Full catalogue and local-library comparison'),('../../../anticoherent-state-catalogue/research/cross-catalogue/verification.json','Exact verification of imported pure states')])+'</section>'
 b+='<section id="controls"><h2>Known neighboring states survive the same equations</h2>'+p('As separate numerical positive controls, the known exact fourth-order states at twelve and fourteen qubits produce trace-one, positive invariant moments satisfying the same contraction construction. Their residuals are below '+m(r'2\times10^{-16}',False)+'. These checks validate the implementation against existing states; the exclusion itself is the exact trace identity above.')
 b+=links([('construction-positive-controls.tex','Control construction and normalization'),('construction-positive-controls.json','Positive-control results'),('construction-positive-controls.py','Reproduce the physical controls')])+'</section>'
 b+='<footer>'+a('../../index.html#n=13&t=4','Return to the settled entry')+'<span>Exact trace contradiction · no symmetry assumption</span></footer>'
 head='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>N=13: no fourth-order anticoherent state</title><link rel="stylesheet" href="../../vendor/katex/katex.min.css"><script defer src="../../vendor/katex/katex.min.js"></script><style>'+css+'</style><script>document.addEventListener("DOMContentLoaded",()=>document.querySelectorAll("[data-tex]").forEach(el=>{if(window.katex)el.innerHTML=katex.renderToString(el.dataset.tex,{displayMode:el.dataset.display==="true",throwOnError:false,strict:"ignore",trust:false});}));</script></head><body><main>'
 (HERE/'index.html').write_text(head+b+'</main></body></html>\n')
if __name__=='__main__':main()
